QUOTE = "'"


def parse_fields(text):
    """Parse a line like name=Ann; note='hi; there' into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    i, n = 0, len(text)
    while i < n:
        # Key: everything up to the first '=' in this field.
        j = i
        while j < n and text[j] not in ("=", SEP):
            j += 1
        raw_key = text[i:j]
        if j >= n or text[j] == SEP:
            if raw_key.strip():
                raise ValueError(f"field without '=': {raw_key.strip()!r}")
            i = j + 1  # empty field
            continue
        key = raw_key.strip()
        if not key:
            raise ValueError(f"empty key in {text[i:j + 1]!r}")
        i = j + 1
        # Value.
        while i < n and text[i].isspace() and text[i] != SEP:
            i += 1
        if i < n and text[i] == QUOTE:
            i += 1
            chars = []
            closed = False
            while i < n:
                ch = text[i]
                if ch == QUOTE:
                    if i + 1 < n and text[i + 1] == QUOTE:
                        chars.append(QUOTE)
                        i += 2
                        continue
                    closed = True
                    i += 1
                    break
                chars.append(ch)
                i += 1
            if not closed:
                raise ValueError(f"unclosed quote in field {key!r}")
            value = "".join(chars)
            while i < n and text[i] != SEP:
                if not text[i].isspace():
                    raise ValueError(f"text after closing quote in field {key!r}")
                i += 1
        else:
            j = i
            while j < n and text[j] != SEP:
                j += 1
            value = text[i:j].strip()
            i = j
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
        i += 1  # skip the SEP (or run past the end)
    return result
